// Build-time only: read the renderer's catalog without importing it into Electron/runtime.
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { presentationLibrary } from '../apps/desktop/renderer/src/features/chat/generative-ui/openUiLibrary.js';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const skillDirectory = resolve(root, 'skills/display-in-chat');
const spec = presentationLibrary.toSpec();
const lines = [
  '# Display component catalog',
  '',
  'Generated by `pnpm generate:openui-catalog` from the installed presentation library. Do not edit signatures by hand.',
  '',
  'Arguments are positional; use `null` to skip an optional argument. `$binding<T>` means a reactive `$variable`, not a literal. Component names and enum values are case-sensitive. Only `@Set`, `@Reset`, and `Action([...])` are supported as button actions. Ignore upstream references to forms or submission; every control is local to this block.',
  '',
];

for (const group of spec.componentGroups ?? []) {
  lines.push(`## ${group.name === 'Forms' ? 'Local controls' : group.name}`, '');
  for (const name of group.components) {
    const component = spec.components[name];
    if (!component) continue;
    lines.push(`### ${name}`, '', '```text', component.signature, '```', '');
  }
}

// read_skill can load the complete body without granting access outside a workspace.
// Keep the generated catalog in that body, rather than requiring filesystem reads.
const marker = '<!-- Generated OpenUI reference: pnpm generate:openui-catalog -->';
for (const filename of ['SKILL.md', 'SKILL.en-US.md']) {
  const examples = await readFile(resolve(skillDirectory, 'references', filename === 'SKILL.md' ? 'examples.md' : 'examples.en-US.md'), 'utf8');
  const destination = resolve(skillDirectory, filename);
  const instructions = (await readFile(destination, 'utf8')).split(marker)[0].trimEnd();
  await writeFile(destination, `${instructions}\n\n${marker}\n\n${examples.trim()}\n\n${lines.join('\n').trimEnd()}\n`);
}
console.log(`Generated ${Object.keys(spec.components).length} component signatures in both display-in-chat Skill bodies`);
